import { useMemo, useState } from 'react';
import {
  Badge,
  Button,
  Card,
  Chip,
  CircularProgress,
  EmptyState,
  Pagination,
  Stack,
  Text,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'warning' | 'exceeded';

interface Project {
  id: string;
  name: string;
  spent: number;
  quota: number;
  status: ProjectStatus;
}

interface ProjectSpendPanelProps {
  projects: Project[];
  pageSize?: number;
}

const STATUS_META: Record<ProjectStatus, { label: string; tone: 'success' | 'warning' | 'danger' }> = {
  active: { label: 'В норме', tone: 'success' },
  warning: { label: 'Близко к лимиту', tone: 'warning' },
  exceeded: { label: 'Лимит превышен', tone: 'danger' },
};

const ALL_STATUSES = Object.keys(STATUS_META) as ProjectStatus[];

function toPercent(spent: number, quota: number): number {
  if (quota <= 0) return 0;
  return Math.min(100, Math.round((spent / quota) * 100));
}

export default function ProjectSpendPanel({ projects, pageSize = 5 }: ProjectSpendPanelProps) {
  const [statuses, setStatuses] = useState<ProjectStatus[]>(ALL_STATUSES);
  const [page, setPage] = useState(1);

  const filtered = useMemo(
    () => projects.filter((project) => statuses.includes(project.status)),
    [projects, statuses],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / pageSize));
  const currentPage = Math.min(page, pageCount);
  const rows = filtered.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  const toggleStatus = (status: ProjectStatus) => {
    setPage(1);
    setStatuses((prev) =>
      prev.includes(status) ? prev.filter((item) => item !== status) : [...prev, status],
    );
  };

  const resetFilters = () => {
    setPage(1);
    setStatuses(ALL_STATUSES);
  };

  return (
    <Card padding="lg">
      <Stack direction="column" style={{ gap: 'var(--jx-space-5)' }}>
        <Stack direction="row" wrap style={{ gap: 'var(--jx-space-2)' }}>
          {ALL_STATUSES.map((status) => (
            <Chip
              key={status}
              selected={statuses.includes(status)}
              tone={STATUS_META[status].tone}
              onClick={() => toggleStatus(status)}
              aria-pressed={statuses.includes(status)}
            >
              {STATUS_META[status].label}
            </Chip>
          ))}
        </Stack>

        {rows.length === 0 ? (
          <EmptyState
            title="Проектов не найдено"
            description="Ни один проект не подходит под выбранные статусы."
            action={
              <Button variant="primary" onClick={resetFilters}>
                Сбросить фильтры
              </Button>
            }
          />
        ) : (
          <Stack direction="column" style={{ gap: 'var(--jx-space-3)' }}>
            {rows.map((project) => {
              const percent = toPercent(project.spent, project.quota);
              const meta = STATUS_META[project.status];

              return (
                <Stack
                  key={project.id}
                  direction="row"
                  align="center"
                  justify="space-between"
                  style={{
                    gap: 'var(--jx-space-4)',
                    padding: 'var(--jx-space-3)',
                    borderRadius: 'var(--jx-radius-md)',
                    background: 'var(--jx-color-surface-subtle)',
                  }}
                >
                  <Text weight="medium" truncate>
                    {project.name}
                  </Text>
                  <Stack direction="row" align="center" style={{ gap: 'var(--jx-space-4)' }}>
                    <CircularProgress
                      value={percent}
                      size="sm"
                      tone={meta.tone}
                      label={`${percent}%`}
                      aria-label={`Квота проекта ${project.name} использована на ${percent}%`}
                    />
                    <Badge tone={meta.tone}>{meta.label}</Badge>
                  </Stack>
                </Stack>
              );
            })}

            {pageCount > 1 && (
              <Pagination page={currentPage} pageCount={pageCount} onPageChange={setPage} />
            )}
          </Stack>
        )}
      </Stack>
    </Card>
  );
}

